function wz_venue_update_path(string $root, string $relativePath): string
{
    $parts = explode('/', $relativePath);

    if ($relativePath === '' || str_contains($relativePath, '\\')) {
        throw new RuntimeException('Unsafe path: ' . $relativePath);
    }

    $path = $root;
    $nearestParent = $root;

    foreach ($parts as $index => $part) {
        if ($part === '' || $part === '.' || $part === '..') {
            throw new RuntimeException('Unsafe path: ' . $relativePath);
        }

        $path .= '/' . $part;

        if (is_link($path)) {
            throw new RuntimeException('Unsafe symlink: ' . $relativePath);
        }

        if ($index < count($parts) - 1 && file_exists($path)) {
            if (!is_dir($path)) {
                throw new RuntimeException('Unsafe parent folder: ' . $relativePath);
            }

            $nearestParent = $path;
        }
    }

    if (!is_writable($nearestParent)) {
        throw new RuntimeException('Unwritable parent folder: ' . $relativePath);
    }

    return $path;
}

function wz_venue_update_read(string $path): ?string
{
    if (!file_exists($path)) {
        return null;
    }

    if (!is_file($path)) {
        throw new RuntimeException('Cannot replace a non-file: ' . basename($path));
    }

    $content = file_get_contents($path);

    if ($content === false) {
        throw new RuntimeException('Cannot read ' . basename($path));
    }

    return $content;
}

function wz_venue_update_decode(array $entry, string $relativePath): string
{
    $compressed = base64_decode((string)($entry['content_gzip_base64'] ?? ''), true);
    $content = $compressed === false ? false : gzdecode($compressed);

    if ($content === false
        || !hash_equals((string)($entry['sha256'] ?? ''), hash('sha256', $content))
    ) {
        throw new RuntimeException('Invalid payload: ' . $relativePath);
    }

    if (str_ends_with($relativePath, '.php')) {
        token_get_all($content, TOKEN_PARSE);
    }

    return $content;
}

function wz_venue_update_mkdir(string $root, string $relativePath, array &$createdDirectories): void
{
    $parent = dirname($relativePath);

    if ($parent === '.') {
        return;
    }

    $path = $root;

    foreach (explode('/', $parent) as $part) {
        $path .= '/' . $part;

        if (is_link($path) || (file_exists($path) && !is_dir($path))) {
            throw new RuntimeException('Unsafe parent folder: ' . $relativePath);
        }

        if (!is_dir($path)) {
            if (!mkdir($path, 0755)) {
                throw new RuntimeException('Cannot create the folder for ' . $relativePath);
            }

            $createdDirectories[] = $path;
        }
    }
}

$root = realpath(getcwd() ?: '');
$backupDirectory = '';
$originals = [];
$modes = [];
$changes = [];
$staged = [];
$installed = [];
$createdDirectories = [];
$addedVenues = 0;
$lock = null;

try {
    if (!$root || !is_file($root . '/includes/bootstrap.php') || !is_file($root . '/includes/database.php')) {
        throw new RuntimeException('Run from the website folder: cd ~/public_html');
    }

    if (!function_exists('token_get_all') || !function_exists('gzdecode') || !is_writable(dirname($root))) {
        throw new RuntimeException('PHP tokenizer, zlib and a writable folder outside public_html are required.');
    }

    if (stat($root)['dev'] !== stat(dirname($root))['dev']) {
        throw new RuntimeException('The website and backup folder must be on the same filesystem.');
    }

    $lockPath = dirname($root) . '/.weddingza-venue-update.lock';

    if (is_link($lockPath)) {
        throw new RuntimeException('Cannot safely open the update lock.');
    }

    $lock = fopen($lockPath, 'c');

    if (!$lock || !flock($lock, LOCK_EX | LOCK_NB)) {
        throw new RuntimeException('Another venue update is running. Try again after it finishes.');
    }

    chmod($lockPath, 0600);

    foreach ($payload['files'] as $relativePath => $entry) {
        $path = wz_venue_update_path($root, $relativePath);
        $original = wz_venue_update_read($path);
        $originals[$relativePath] = $original;
        $modes[$relativePath] = $original !== null ? fileperms($path) & 0777 : 0644;
        $currentHash = $original !== null ? hash('sha256', $original) : null;
        $updated = wz_venue_update_decode($entry, $relativePath);

        if ($currentHash === $entry['sha256']) {
            continue;
        }

        if (!in_array($currentHash, array_column($entry['baselines'], 'sha256'), true)) {
            throw new RuntimeException($relativePath . ' has a different version or local edits. No website files have been changed.');
        }

        $changes[$relativePath] = $updated;
    }

    // Merge only the new records. Existing IDs or names and all other owner settings win.
    $dataPath = 'assets/data/site.json';
    $dataFile = wz_venue_update_path($root, $dataPath);
    $originalData = wz_venue_update_read($dataFile);
    $data = json_decode($originalData ?? '', true, 512, JSON_THROW_ON_ERROR);

    if (!is_array($data) || !isset($data['vendors']) || !is_array($data['vendors']) || !array_is_list($data['vendors'])) {
        throw new RuntimeException('The venue catalogue is invalid. No website files have been changed.');
    }

    $seeds = json_decode(wz_venue_update_decode($payload['venues'], $dataPath), true, 512, JSON_THROW_ON_ERROR);

    foreach ($seeds as $seed) {
        $alreadyPresent = false;

        foreach ($data['vendors'] as $existing) {
            if (!is_array($existing)) {
                throw new RuntimeException('The venue catalogue contains an invalid listing.');
            }

            if ((string)($existing['id'] ?? '') === (string)$seed['id']
                || strcasecmp(trim((string)($existing['name'] ?? '')), trim((string)$seed['name'])) === 0
            ) {
                $alreadyPresent = true;
                break;
            }
        }

        if (!$alreadyPresent) {
            $data['vendors'][] = $seed;
            $addedVenues++;
        }
    }

    $originals[$dataPath] = $originalData;
    $modes[$dataPath] = fileperms($dataFile) & 0777;

    if ($addedVenues > 0) {
        $changes[$dataPath] = json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR) . "\n";
    }

    if (!$changes) {
        echo "Venue collection upgrade is already installed.\n";
        echo "Open https://weddingza.com/venues.php and press Ctrl+Shift+R.\n";
    } else {
        $backupDirectory = dirname($root) . '/weddingza-venue-backup-'
            . gmdate('Ymd-His') . '-' . bin2hex(random_bytes(4));

        if (!mkdir($backupDirectory, 0700)) {
            throw new RuntimeException('Cannot prepare the backup folder.');
        }

        foreach ($changes as $relativePath => $updated) {
            $backupFile = $backupDirectory . '/' . $relativePath;

            if (!is_dir(dirname($backupFile)) && !mkdir(dirname($backupFile), 0700, true)) {
                throw new RuntimeException('Cannot prepare the backup for ' . $relativePath);
            }

            $original = $originals[$relativePath];

            if ($original !== null
                && (file_put_contents($backupFile, $original) !== strlen($original) || !chmod($backupFile, 0600))
            ) {
                throw new RuntimeException('Cannot back up ' . $relativePath);
            }

            $staged[$relativePath] = $backupFile . '.new';

            if (file_put_contents($staged[$relativePath], $updated) !== strlen($updated)
                || !chmod($staged[$relativePath], $modes[$relativePath])
                || hash_file('sha256', $staged[$relativePath]) !== hash('sha256', $updated)
            ) {
                throw new RuntimeException('Cannot stage ' . $relativePath);
            }
        }

        // Recheck every source before publishing any file, including the owner catalogue.
        foreach ($originals as $relativePath => $original) {
            $path = wz_venue_update_path($root, $relativePath);

            if (wz_venue_update_read($path) !== $original) {
                throw new RuntimeException('A file changed during preparation: ' . $relativePath);
            }
        }

        foreach (array_keys($changes) as $relativePath) {
            wz_venue_update_mkdir($root, $relativePath, $createdDirectories);
        }

        foreach ($changes as $relativePath => $updated) {
            $path = wz_venue_update_path($root, $relativePath);

            if (wz_venue_update_read($path) !== $originals[$relativePath]
                || !rename($staged[$relativePath], $path)
            ) {
                throw new RuntimeException('Cannot install ' . $relativePath);
            }

            $installed[] = $relativePath;
        }

        echo "Venue collection upgrade installed.\n";
        echo 'Existing catalogue records changed: ' . $addedVenues . "\n";
        echo 'Original files backed up in: ' . $backupDirectory . "\n";
        echo "Open https://weddingza.com/venues.php and press Ctrl+Shift+R.\n";
    }
} catch (Throwable $error) {
    $rollbackFailed = false;

    foreach (array_reverse($installed) as $relativePath) {
        $path = $root . '/' . $relativePath;

        if ($originals[$relativePath] === null) {
            $restored = unlink($path);
        } else {
            $backupFile = $backupDirectory . '/' . $relativePath;
            $restoreFile = $backupFile . '.restore';
            $restored = copy($backupFile, $restoreFile)
                && chmod($restoreFile, $modes[$relativePath])
                && rename($restoreFile, $path);
        }

        $rollbackFailed = $rollbackFailed || !$restored;
    }

    foreach (array_reverse($createdDirectories) as $directory) {
        if (is_dir($directory) && count(scandir($directory)) === 2) {
            rmdir($directory);
        }
    }

    fwrite(STDERR, 'Update stopped: ' . $error->getMessage() . "\n");

    if ($installed) {
        fwrite(STDERR, $rollbackFailed
            ? 'Restore could not finish. Original files remain in: ' . $backupDirectory . "\n"
            : "Website changes were rolled back.\n");
    }

    exit(1);
} finally {
    if (is_resource($lock)) {
        flock($lock, LOCK_UN);
        fclose($lock);
    }
}
